('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', 'Plates sliding past each other:', 'Trench', 'Convergent', 'Transform fault', 'Divergent', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', 'Soft flowing layer under plates:', 'Crust', 'Core', 'Asthenosphere', 'Lithosphere', 'C', 'Option C is the correct answer.', true),
